// Demo: 业务错误码 — internal/errcode/order.go
// 对应 error-codes.md §5：错误码字面量只允许出现在 errcode 包；其余代码一律引用这里的函数。
// 先在 docs/error-codes.yaml 登记，再在这里定义（同一个 PR）。
package errcode

import "gin-go-common-lib/errors"

// 订单模块（SERVICE=TRADE, MODULE=ORDER）。
// 用「返回新实例的函数」而不是包级 var，避免多处共享同一指针被误改。

// OrderPriceOutOfRange 价格超出允许区间（001-099 业务校验，HTTP 400）。
func OrderPriceOutOfRange() *errors.AppError {
	return &errors.AppError{Code: "TRADE_ORDER_001", Msg: "order price is out of the allowed range", HTTPStatus: 400}
}

// OrderNotFound 订单不存在（200-299 资源不存在，HTTP 404）。
func OrderNotFound() *errors.AppError {
	return &errors.AppError{Code: "TRADE_ORDER_201", Msg: "order not found", HTTPStatus: 404}
}

// OrderStatusConflict 订单状态流转冲突 / 乐观锁冲突（300-399，HTTP 409）。
func OrderStatusConflict() *errors.AppError {
	return &errors.AppError{Code: "TRADE_ORDER_301", Msg: "order status transition conflict", HTTPStatus: 409}
}

// 使用方式（biz 层返回，handler 层统一出口）：
//
//	// biz
//	order, err := uc.repo.GetByID(ctx, id)
//	if err != nil {
//	    if errors.Is(err) { return nil, err }            // 已是 AppError，原样上抛
//	    return nil, fmt.Errorf("get order %s: %w", id, err) // 其余包装保留错误链
//	}
//	if order == nil { return nil, errcode.OrderNotFound() }
//
//	// handler
//	if err != nil { response.FailErr(c, err); return }
//
// 注意：非 AppError 会被 FailErr 当作 COMMON_COMMON_501 返回且不暴露原文，
// 所以原始 error 必须在返回前由调用方记录日志（带 trace_id）。

// Demo: 最小 Gin 服务骨架 — cmd/trade/main.go
// 使用 gin-go-common-lib：logging / middleware / response / errors / idempotency / storage
// 分层：handler → biz → data（此处为演示合并在一个文件，真实项目按 go-style.md §2 拆到 internal/ 各包）
package main

import (
	"context"
	"errors"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	apperr "gin-go-common-lib/errors"
	"gin-go-common-lib/idempotency"
	"gin-go-common-lib/logging"
	"gin-go-common-lib/metrics"
	"gin-go-common-lib/middleware"
	"gin-go-common-lib/response"
	"gin-go-common-lib/storage/db"
	rds "gin-go-common-lib/storage/redis"
	"gin-go-common-lib/transport/header"

	"github.com/gin-gonic/gin"
)

// ───────── biz 层：业务规则，不依赖 gin / gorm / redis ─────────

// CreateOrderInput 是 biz 层的入参（与 HTTP 请求结构解耦）。
type CreateOrderInput struct {
	UID      string
	Symbol   string
	Price    string // 金额类一律 string，biz 内用 decimal 运算
	Quantity string
}

// OrderUsecase 下单用例。repo 等依赖通过构造函数注入。
type OrderUsecase struct {
	log *logging.Logger
}

// NewOrderUsecase 构造函数注入，不使用全局变量。
func NewOrderUsecase(log *logging.Logger) *OrderUsecase { return &OrderUsecase{log: log} }

// CreateOrder 返回订单 ID。业务错误统一返回 *errors.AppError（见 apperror.go）。
func (u *OrderUsecase) CreateOrder(ctx context.Context, in CreateOrderInput) (string, error) {
	if in.Symbol == "" {
		return "", apperr.ErrValidation("symbol is required")
	}
	// ... 校验精度 → 冻结资金 → 事务内写 orders + outbox_events → 返回 ID（见 kafka.md §5）
	u.log.Info(ctx, "order created", "uid", in.UID, "symbol", in.Symbol)
	return "0194f3a2-7c1e-7b52-9d0a-3f6c2e8a1b45", nil
}

// ───────── handler 层：只做绑定校验 → 调 biz → 输出 ─────────

// CreateOrderReq JSON 字段一律 snake_case；金额类用 string。
type CreateOrderReq struct {
	Symbol   string `json:"symbol" binding:"required"`
	Price    string `json:"price" binding:"required"`
	Quantity string `json:"quantity" binding:"required"`
}

// OrderHandler HTTP 适配层。
type OrderHandler struct{ uc *OrderUsecase }

// Create POST /api/v1/orders
func (h *OrderHandler) Create(c *gin.Context) {
	var req CreateOrderReq
	if !response.BindJSONOrFail(c, &req) {
		return
	}
	// X-User-Id 由网关鉴权后注入，经 middleware.TraceID 放入 ctx
	uid, ok := header.GetUserID(c.Request.Context())
	if !ok {
		response.FailErr(c, apperr.ErrUnauthorized("missing user"))
		return
	}
	id, err := h.uc.CreateOrder(c.Request.Context(), CreateOrderInput{
		UID: uid, Symbol: req.Symbol, Price: req.Price, Quantity: req.Quantity,
	})
	if err != nil {
		response.FailErr(c, err) // AppError 自动映射 HTTP 状态码与业务码
		return
	}
	response.JSON(c, gin.H{"order_id": id})
}

// ───────── 启动入口：读配置 → 构造依赖 → 注册路由 → 优雅退出 ─────────

func main() {
	log := logging.New("trade-service")
	reg := metrics.NewRegistry()

	// MySQL：公共库已带慢查询日志与连接池（单服务上限 ≤ 50，见 database.md §2.3）。
	// DSN 必带：charset=utf8mb4&parseTime=true&loc=UTC&clientFoundRows=true&timeout=3s&readTimeout=35s&writeTimeout=5s
	gdb, err := db.NewMySQL(db.Config{
		Driver:       "mysql",
		Source:       os.Getenv("MYSQL_DSN"), // 密钥走环境变量，禁止硬编码
		MaxOpenConns: 50,
		MaxIdleConns: 10,
	}, log)
	if err != nil {
		log.Error(context.Background(), "init mysql failed", "err", err)
		os.Exit(1)
	}
	_ = gdb // 传给 data 层的 repo

	rdb, err := rds.New(rds.Config{Mode: "single", Addr: os.Getenv("REDIS_ADDR"), Password: os.Getenv("REDIS_PASSWORD")})
	if err != nil {
		log.Error(context.Background(), "init redis failed", "err", err)
		os.Exit(1)
	}

	r := gin.New()
	r.Use(middleware.Default(log, reg)...) // TraceID → Recovery → Logger → Metrics
	r.GET("/healthz", func(c *gin.Context) { response.JSON(c, gin.H{"status": "ok"}) })
	r.GET(metrics.DefaultPath, gin.WrapH(reg.Handler()))

	h := &OrderHandler{uc: NewOrderUsecase(log)}
	v1 := r.Group("/api/v1")
	// 幂等：X-Idempotency-Key；Redis 异常时放行，最终幂等仍靠 MySQL 唯一键（redis.md §6）
	v1.POST("/orders", idempotency.Middleware(idempotency.NewRedisStore(rdb), 24*time.Hour), h.Create)

	srv := &http.Server{Addr: ":8080", Handler: r, ReadHeaderTimeout: 5 * time.Second}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	go func() { // 受 ctx / Shutdown 管控的 goroutine
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error(ctx, "http server exited", "err", err)
			stop()
		}
	}()

	<-ctx.Done()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Error(shutdownCtx, "http shutdown failed", "err", err)
	}
}

// Demo: Kafka 消费者 — internal/job/fill_consumer.go
// 对应 kafka.md §4：必须幂等（同事务写去重表）、handler 内自己重试 + 死信（不能依赖“返回 error 让 Kafka 重试”）。
//
// ⚠️ 公共库 mq.Consumer 在 handler 返回 error 时只是 continue：不提交该条，也不会重新投递，
// 后续消息提交成功后 offset 会越过它 → 该消息被静默丢弃。所以本 demo 的 handler 对“已处置”的消息一律返回 nil。
package job

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"gin-go-common-lib/logging"
	"gin-go-common-lib/mq"
	"gin-go-common-lib/naming"

	"github.com/go-sql-driver/mysql"
	"gorm.io/gorm"
)

const maxAttempts = 3

var backoffs = []time.Duration{1 * time.Second, 5 * time.Second, 30 * time.Second}

// envelope 与发布方的 Envelope 一致。真实项目消费方应引用发布方的 contract 包，禁止自己重新定义。
type envelope struct {
	EventID    string          `json:"event_id"`
	EventType  string          `json:"event_type"`
	PlatformID string          `json:"platform_id"`
	Payload    json.RawMessage `json:"payload"`
}

// errNonRetryable 表示重试也没用（消息非法、业务规则拒绝），直接进死信。
var errNonRetryable = errors.New("non-retryable")

// DLQPublisher 写死信 Topic 的最小接口（由 kafkap.Publisher 之类实现）。
type DLQPublisher interface {
	PublishRaw(ctx context.Context, topic string, key, value []byte) error
}

// FillConsumer 成交回报消费者。
type FillConsumer struct {
	db    *gorm.DB
	dlq   DLQPublisher
	log   *logging.Logger
	env   string
	group string
}

// NewFillConsumer 构造函数注入。
func NewFillConsumer(db *gorm.DB, dlq DLQPublisher, log *logging.Logger, env string) *FillConsumer {
	return &FillConsumer{db: db, dlq: dlq, log: log, env: env, group: naming.ConsumerGroup("trade_service", "fill_consume")}
}

// Run 阻塞消费；ctx 取消时退出。
func (c *FillConsumer) Run(ctx context.Context, brokers []string) error {
	topic := naming.TopicInProject(c.env, "matching", "trade", "matched")
	consumer := mq.NewConsumer(mq.ConsumerConfig{Brokers: brokers, GroupID: c.group, Topic: topic}, c.handle)
	defer consumer.Close()
	return consumer.Start(ctx)
}

// handle 对每条消息：重试 → 仍失败则写死信 → 返回 nil（本条已处置）。
func (c *FillConsumer) handle(ctx context.Context, msg mq.Message) error {
	var lastErr error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		lastErr = c.process(ctx, msg)
		if lastErr == nil {
			return nil
		}
		if errors.Is(lastErr, errNonRetryable) {
			break
		}
		select { // 退避期间也要响应 ctx 取消
		case <-ctx.Done():
			return nil
		case <-time.After(backoffs[attempt]):
		}
	}
	c.log.Error(ctx, "consume failed, send to dlq", "topic", msg.Topic, "offset", msg.Offset, "err", lastErr)
	dlqCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	if err := c.dlq.PublishRaw(dlqCtx, msg.Topic+"_dlq", msg.Key, msg.Value); err != nil {
		c.log.Error(ctx, "write dlq failed", "topic", msg.Topic, "offset", msg.Offset, "err", err)
	}
	return nil // 无论如何返回 nil：已重试 + 已尝试死信，不能依赖返回 error 触发重投
}

// process 单次处理：同一事务内“写去重表 + 业务变更 + 写 outbox”。
func (c *FillConsumer) process(ctx context.Context, msg mq.Message) error {
	var env envelope
	if err := json.Unmarshal(msg.Value, &env); err != nil || env.EventID == "" {
		return fmt.Errorf("%w: bad envelope: %v", errNonRetryable, err)
	}
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	return c.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		// 1) 去重：唯一键 (consumer_group, event_id)。1062 说明已处理过，视为成功。
		now := time.Now().UnixMilli()
		err := tx.Exec(
			"INSERT INTO trade.consumed_events (consumer_group, event_id, create_time, update_time) VALUES (?, ?, ?, ?)", // id 自增由库生成；去重表是纯技术表，无 oid
			c.group, env.EventID, now, now,
		).Error
		if err != nil {
			var me *mysql.MySQLError
			if errors.As(err, &me) && me.Number == 1062 {
				return nil
			}
			return fmt.Errorf("insert consumed_events: %w", err)
		}
		// 2) 业务变更：乐观锁更新订单 filled_qty / order_status（每条 UPDATE 必写 update_time）
		// 3) 同事务写 outbox_events，由 relay 发布 order_status_updated
		return nil
	})
}

// Demo: Kafka 发布事件 — internal/data/event_publisher.go
// 对应 kafka.md：Topic 由 naming 包构造；统一消息信封；PublishWithHeaders 带 trace_id / platform_id / idempotency_key；Publish 必带超时。
// 注意：业务代码不要在“提交 MySQL 之后”直接调用本发布器——会丢消息。
// 业务事务内只写 outbox_events（见 outbox-relay.go），由 relay 调用本发布器发送。
package data

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"gin-go-common-lib/logging"
	"gin-go-common-lib/mq"
	"gin-go-common-lib/naming"
)

// Envelope 统一消息信封（kafka.md §2.1）。字段 snake_case，时间为毫秒时间戳。
type Envelope struct {
	EventID       string          `json:"event_id"`       // UUIDv7，消费端幂等依据
	EventType     string          `json:"event_type"`     // 如 order.pay_status_updated
	SchemaVersion int             `json:"schema_version"` // 载荷结构版本
	OccurredTime  int64           `json:"occurred_time"`  // 毫秒时间戳 UTC
	PlatformID    string          `json:"platform_id"`
	Payload       json.RawMessage `json:"payload"`
}

// Publisher 事件发布器。
type Publisher struct {
	producer *mq.Producer
	env      string // dev / test / staging / prod
	log      *logging.Logger
}

// NewPublisher 构造函数注入。生产环境 Topic 由运维预建，不依赖 Producer 自动建 Topic。
func NewPublisher(brokers []string, env string, log *logging.Logger) *Publisher {
	naming.MustValidateKafkaEnv(env) // 启动期校验环境名，不合规直接 panic（仅允许在启动阶段）
	return &Publisher{
		producer: mq.NewProducer(mq.ProducerConfig{Brokers: brokers, ClientID: "trade-service"}),
		env:      env,
		log:      log,
	}
}

// OrderStatusTopic 构造订单状态事件 Topic：{env}_{service}_{biz}_{action}，一律走 naming。
func (p *Publisher) OrderStatusTopic() string {
	return naming.TopicInProject(p.env, "trade", "order_status", "updated")
}

// Publish 发送一条事件。key 用业务主键（如 order_id），保证同一订单进同一分区、有序。
func (p *Publisher) Publish(ctx context.Context, topic, key string, env Envelope, traceID string) error {
	body, err := json.Marshal(env)
	if err != nil {
		return fmt.Errorf("marshal envelope: %w", err)
	}
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second) // Publish 必带超时（铁律 13）
	defer cancel()
	headers := map[string]string{
		"trace_id":        traceID,
		"platform_id":     env.PlatformID,
		"idempotency_key": env.EventID,
	}
	if err := p.producer.PublishWithHeaders(ctx, topic, []byte(key), body, headers); err != nil {
		// 日志不记录消息体（可能含敏感数据），只记录定位信息
		p.log.Error(ctx, "publish event failed", "topic", topic, "event_id", env.EventID, "err", err)
		return fmt.Errorf("publish %s: %w", topic, err)
	}
	return nil
}

// PublishRaw 原样转发一条消息（用于写死信 Topic：{原 topic}_dlq）。
func (p *Publisher) PublishRaw(ctx context.Context, topic string, key, value []byte) error {
	return p.producer.Publish(ctx, topic, key, value)
}

// Close 优雅退出时关闭。
func (p *Publisher) Close() error { return p.producer.Close() }

// Demo: GORM + MySQL 仓储 — internal/data/order_repo.go
// 对应 database.md：ctx + 超时、无软删除（物理删除）、游标分页、乐观锁、自增 id + UUIDv7 oid、create_time/update_time 毫秒
package data

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"

	apperr "gin-go-common-lib/errors"

	"github.com/go-sql-driver/mysql"
	"github.com/google/uuid"
	"github.com/shopspring/decimal"
	"gorm.io/gorm"
)

const (
	queryTimeout = 3 * time.Second // 所有 DB 调用必带超时（铁律 13）
	maxOIDRetry  = 3               // oid 撞号最多重新生成 3 次（id-generation.md §4）
	oidIndexName = "uk_orders_oid"
)

// OrderPO 对应 trade.orders。字段 / 类型严格对照 database.md §4.10。
//
//	ID  自增主键：库内物理主键，只在本包内部使用（游标 tie-breaker），不得进入 DTO / 事件 / 缓存 Key，不被其他表引用。
//	OID 业务 ID：UUIDv7 小写 36 位，应用层生成；对外、跨表引用（{entity}_oid）一律用它。
type OrderPO struct {
	ID            uint64          `gorm:"column:id;primaryKey;autoIncrement"`
	OID           string          `gorm:"column:oid"`
	PlatformID    string          `gorm:"column:platform_id"`
	UID           string          `gorm:"column:uid"`
	ClientOrderID string          `gorm:"column:client_order_id"`
	Symbol        string          `gorm:"column:symbol"`
	OrderSide     uint8           `gorm:"column:order_side"` // 1=买 2=卖
	OrderType     uint8           `gorm:"column:order_type"` // 1=限价 2=市价
	Price         decimal.Decimal `gorm:"column:price;type:decimal(38,18)"`
	Quantity      decimal.Decimal `gorm:"column:quantity;type:decimal(38,18)"`
	FilledQty     decimal.Decimal `gorm:"column:filled_qty;type:decimal(38,18)"`
	OrderStatus   uint8           `gorm:"column:order_status"`
	Version       uint32          `gorm:"column:version"`
	// 毫秒时间戳由应用层写入；GORM 的 autoCreateTime/autoUpdateTime:milli 会自动填，
	// 但手写 SQL / 批量更新不会触发，必须手动写 update_time（见 UpdateStatus）。
	CreateTime int64 `gorm:"column:create_time;autoCreateTime:milli"`
	UpdateTime int64 `gorm:"column:update_time;autoUpdateTime:milli"`
	// created_at / updated_at 由数据库维护，应用层只读（<-:false），业务代码不得读取。
	CreatedAt time.Time `gorm:"column:created_at;<-:false"`
	UpdatedAt time.Time `gorm:"column:updated_at;<-:false"`
}

// TableName 库名.表名。
func (OrderPO) TableName() string { return "trade.orders" }

// NewOID 生成业务 ID：UUIDv7，36 位小写。真实项目走公共库 util/idgen（目前该库只有 UUIDv4，需先补 UUIDv7）。
func NewOID() (string, error) {
	u, err := uuid.NewV7()
	if err != nil {
		return "", fmt.Errorf("gen oid: %w", err)
	}
	return u.String(), nil // google/uuid 的 String() 恒为小写
}

// NormalizeOID 校验并归一为小写 36 位。库默认 utf8mb4_0900_bin 区分大小写：
// 大写 oid 既查不到小写行，还能绕过唯一索引写入重复行，所以进出库前必须归一。
func NormalizeOID(s string) (string, error) {
	u, err := uuid.Parse(strings.TrimSpace(s))
	if err != nil {
		return "", fmt.Errorf("invalid oid %q: %w", s, err)
	}
	return u.String(), nil
}

// OrderRepo 订单仓储。接口定义在 biz 包，这里是实现。
type OrderRepo struct{ db *gorm.DB }

// NewOrderRepo 构造函数注入。
func NewOrderRepo(db *gorm.DB) *OrderRepo { return &OrderRepo{db: db} }

// Create 插入订单。oid 为空则由本函数生成。
//   - 命中 uk_orders_oid（oid 撞号，概率极低）：重新生成 oid 重试，最多 maxOIDRetry 次；
//   - 命中其他唯一键（如 client_order_id 幂等键）：返回 ErrConflict，由 biz 按幂等处理，不得换 oid 重试。
//
// 成功后业务只需要 o.OID；o.ID 是 GORM 回填的自增主键，不要往外传。
func (r *OrderRepo) Create(ctx context.Context, o *OrderPO) error {
	for attempt := 0; attempt < maxOIDRetry; attempt++ {
		if o.OID == "" || attempt > 0 {
			oid, err := NewOID()
			if err != nil {
				return err
			}
			o.OID = oid
		} else {
			oid, err := NormalizeOID(o.OID)
			if err != nil {
				return err
			}
			o.OID = oid
		}
		o.ID = 0
		err := r.insert(ctx, o)
		if err == nil {
			return nil
		}
		key, dup := duplicateKey(err)
		if !dup {
			return fmt.Errorf("create order: %w", err)
		}
		if !strings.HasSuffix(key, oidIndexName) {
			return apperr.ErrConflict("duplicate order") // 业务唯一键冲突 = 幂等重复
		}
		// 命中 oid 唯一索引：进入下一轮，重新生成
	}
	return fmt.Errorf("create order: oid collision after %d attempts", maxOIDRetry)
}

func (r *OrderRepo) insert(ctx context.Context, o *OrderPO) error {
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	return r.db.WithContext(ctx).Create(o).Error
}

// GetByOID 按业务 ID 查询；不存在返回 (nil, nil)，由 biz 转成 OrderNotFound。禁止 SELECT *：显式列出字段。
func (r *OrderRepo) GetByOID(ctx context.Context, oid string) (*OrderPO, error) {
	oid, err := NormalizeOID(oid)
	if err != nil {
		return nil, err
	}
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	var o OrderPO
	err = r.db.WithContext(ctx).
		Select("id", "oid", "platform_id", "uid", "client_order_id", "symbol", "order_side", "order_type", "price", "quantity",
			"filled_qty", "order_status", "version", "create_time", "update_time").
		Where("oid = ?", oid).Take(&o).Error
	if errors.Is(err, gorm.ErrRecordNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get order: %w", err)
	}
	return &o, nil
}

// UpdateStatus 乐观锁更新。返回 false 表示版本冲突（需 DSN 开启 clientFoundRows=true，否则“值没变”也会返回 0）。
// 每条 UPDATE 都必须写 update_time（database.md §4.1）。
func (r *OrderRepo) UpdateStatus(ctx context.Context, oid string, status uint8, filled decimal.Decimal, version uint32) (bool, error) {
	oid, err := NormalizeOID(oid)
	if err != nil {
		return false, err
	}
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	res := r.db.WithContext(ctx).Model(&OrderPO{}).
		Where("oid = ? AND version = ?", oid, version).
		Updates(map[string]any{
			"order_status": status,
			"filled_qty":   filled,
			"version":      gorm.Expr("version + 1"),
			"update_time":  time.Now().UnixMilli(),
		})
	if res.Error != nil {
		return false, fmt.Errorf("update order status: %w", res.Error)
	}
	return res.RowsAffected == 1, nil
}

// ListByCursor 游标分页：以 create_time 为主、自增 id 仅作同毫秒 tie-breaker，禁止 OFFSET 大翻页。
// 首次查询传 cursorTime=0。cursorID 只在服务内部使用：返回给前端的游标令牌须做不透明编码，不得直接暴露自增 id。
func (r *OrderRepo) ListByCursor(ctx context.Context, platformID, uid string, cursorTime int64, cursorID uint64, limit int) ([]OrderPO, error) {
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	q := r.db.WithContext(ctx).
		Select("id", "oid", "symbol", "order_side", "order_type", "price", "quantity", "filled_qty", "order_status", "create_time").
		Where("platform_id = ? AND uid = ?", platformID, uid)
	if cursorTime > 0 {
		q = q.Where("(create_time < ? OR (create_time = ? AND id < ?))", cursorTime, cursorTime, cursorID)
	}
	var list []OrderPO
	if err := q.Order("create_time DESC, id DESC").Limit(limit).Find(&list).Error; err != nil {
		return nil, fmt.Errorf("list orders: %w", err)
	}
	return list, nil
}

// DeleteByOID 物理删除（本项目不使用软删除）。资金类数据删除前须先归档，见 database.md §4.4。
func (r *OrderRepo) DeleteByOID(ctx context.Context, oid string) error {
	oid, err := NormalizeOID(oid)
	if err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	if err := r.db.WithContext(ctx).Where("oid = ?", oid).Delete(&OrderPO{}).Error; err != nil {
		return fmt.Errorf("delete order: %w", err)
	}
	return nil
}

// dupKeyRe 取 MySQL 1062 报错信息里的索引名：Duplicate entry 'x' for key 'orders.uk_orders_oid'
var dupKeyRe = regexp.MustCompile(`for key '([^']+)'`)

// duplicateKey 判断是否 MySQL 唯一键冲突（1062），并返回命中的索引名（形如 "orders.uk_orders_oid"）。
func duplicateKey(err error) (string, bool) {
	var me *mysql.MySQLError
	if !errors.As(err, &me) || me.Number != 1062 {
		return "", false
	}
	if m := dupKeyRe.FindStringSubmatch(me.Message); len(m) == 2 {
		return m[1], true
	}
	return "", true
}

// Demo: Outbox relay — internal/job/outbox_relay.go
// 对应 kafka.md §5：业务事务里只写 outbox_events；relay 轮询待发送记录发到 Kafka，成功后标记已发送。
// 多实例并行用 FOR UPDATE SKIP LOCKED；同一 msg_key 的事件必须串行（本 demo 按取出顺序串行发送）。
package job

import (
	"context"
	"fmt"
	"time"

	"gin-go-common-lib/logging"

	"gorm.io/gorm"
	"gorm.io/gorm/clause"
)

const (
	statusPending = 1 // event_status：1=待发送 2=已发送 3=发送失败
	statusSent    = 2
	statusFailed  = 3
	batchSize     = 100 // 单批 ≤ 100（database.md §7.2）
	maxRetries    = 10
)

// OutboxEvent 对应 trade.outbox_events。
type OutboxEvent struct {
	ID          uint64 `gorm:"column:id;primaryKey;autoIncrement"` // 库内自增主键，仅 relay 内部用（定位行 / 排序）
	OID         string `gorm:"column:oid"`                         // UUIDv7，同时作为信封里的 event_id
	Topic       string `gorm:"column:topic"`
	MsgKey      string `gorm:"column:msg_key"`
	Payload     []byte `gorm:"column:payload"` // JSON 列，已是完整信封
	EventStatus uint8  `gorm:"column:event_status"`
	RetryCount  uint32 `gorm:"column:retry_count"`
	CreateTime  int64  `gorm:"column:create_time"`
	UpdateTime  int64  `gorm:"column:update_time"`
}

// TableName 库名.表名。
func (OutboxEvent) TableName() string { return "trade.outbox_events" }

// Sender 发送一条消息（由 kafkap.Publisher 适配）。
type Sender interface {
	PublishRaw(ctx context.Context, topic string, key, value []byte) error
}

// Relay 轮询发送器。
type Relay struct {
	db     *gorm.DB
	sender Sender
	log    *logging.Logger
}

// NewRelay 构造函数注入。
func NewRelay(db *gorm.DB, sender Sender, log *logging.Logger) *Relay {
	return &Relay{db: db, sender: sender, log: log}
}

// Run 每 200ms 轮询一次；ctx 取消时退出。
func (r *Relay) Run(ctx context.Context) {
	ticker := time.NewTicker(200 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if err := r.flushOnce(ctx); err != nil {
				r.log.Error(ctx, "outbox flush failed", "err", err)
			}
		}
	}
}

// flushOnce 在一个事务里：锁住一批待发送记录 → 逐条发送 → 更新状态。
// 事务期间持有行锁，因此整批处理必须很快（有超时），不要在里面做慢操作。
func (r *Relay) flushOnce(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	return r.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		var events []OutboxEvent
		if err := tx.Clauses(clause.Locking{Strength: "UPDATE", Options: "SKIP LOCKED"}).
			Where("event_status = ?", statusPending).
			Order("create_time ASC, id ASC").Limit(batchSize).Find(&events).Error; err != nil {
			return fmt.Errorf("select outbox: %w", err)
		}
		for _, e := range events {
			sendCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
			err := r.sender.PublishRaw(sendCtx, e.Topic, []byte(e.MsgKey), e.Payload)
			cancel()

			upd := map[string]any{"update_time": time.Now().UnixMilli()} // 每条 UPDATE 必写 update_time
			if err == nil {
				upd["event_status"] = statusSent
			} else {
				upd["retry_count"] = gorm.Expr("retry_count + 1")
				if e.RetryCount+1 >= maxRetries {
					upd["event_status"] = statusFailed // 超限：标记失败并告警，人工处理
					r.log.Error(ctx, "outbox event failed permanently", "topic", e.Topic, "retry", e.RetryCount+1)
				}
			}
			if uerr := tx.Model(&OutboxEvent{}).Where("id = ?", e.ID).Updates(upd).Error; uerr != nil {
				return fmt.Errorf("update outbox: %w", uerr)
			}
			if err != nil {
				break // 保证同一 msg_key 的顺序：这一条失败就停止本批，下一轮从它继续
			}
		}
		return nil
	})
}

// Demo: Redis 缓存 / 分布式锁 — internal/data/cache.go
// 对应 redis.md：Key 由 naming.RedisKey 构造且带 TTL（含随机抖动）；Cache-Aside（先写库后删缓存）；
// redis.Nil 是“未命中”不是错误；singleflight 防击穿；锁用 SET NX PX + Lua 校验 token 释放。
package data

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math/rand/v2"
	"strings"
	"time"

	"gin-go-common-lib/cache/singleflight"
	"gin-go-common-lib/naming"

	"github.com/google/uuid"
	goredis "github.com/redis/go-redis/v9"
)

const (
	redisTimeout = 300 * time.Millisecond // 读写超时（redis.md §9）
	symbolTTL    = 5 * time.Minute
)

// SymbolConfig 交易对配置（示例缓存对象）。
type SymbolConfig struct {
	Symbol        string `json:"symbol"`
	PriceScale    int    `json:"price_scale"`
	MinQuantity   string `json:"min_quantity"` // 金额类一律 string
	IsTradeEnable bool   `json:"is_trade_enable"`
}

// SymbolLoader 回源（查 MySQL）。接口定义在 biz，这里为演示放在一起。
type SymbolLoader func(ctx context.Context, symbol string) (*SymbolConfig, error)

// SymbolCache 交易对配置缓存。
type SymbolCache struct {
	rdb    goredis.UniversalClient
	load   SymbolLoader
	flight singleflight.Group[*SymbolConfig] // 同进程合并回源，防缓存击穿
}

// NewSymbolCache 构造函数注入。
func NewSymbolCache(rdb goredis.UniversalClient, load SymbolLoader) *SymbolCache {
	return &SymbolCache{rdb: rdb, load: load}
}

// symbolKey 构造 trade:symbol:btc-usdt。naming.RedisKey 只接受小写，交易对（BTC-USDT）必须先转小写，否则会 panic。
func symbolKey(symbol string) string {
	return naming.RedisKey("trade", "symbol", strings.ToLower(symbol))
}

// jitter TTL 加 0~20% 随机抖动，防缓存雪崩。
func jitter(base time.Duration) time.Duration {
	return base + time.Duration(rand.Int64N(int64(base)/5))
}

// Get Cache-Aside 读：先 Redis，未命中回源并回填。
func (c *SymbolCache) Get(ctx context.Context, symbol string) (*SymbolConfig, error) {
	key := symbolKey(symbol)
	rctx, cancel := context.WithTimeout(ctx, redisTimeout)
	raw, err := c.rdb.Get(rctx, key).Bytes()
	cancel()
	switch {
	case err == nil:
		var cfg SymbolConfig
		if jerr := json.Unmarshal(raw, &cfg); jerr == nil {
			return &cfg, nil
		}
		// 缓存内容损坏：当作未命中，回源覆盖
	case errors.Is(err, goredis.Nil):
		// 未命中：不是错误，继续回源
	default:
		// Redis 故障：降级直接回源 MySQL（须有限流保护 MySQL），不向调用方返回错误
	}
	return c.flight.Do(key, func() (*SymbolConfig, error) {
		cfg, lerr := c.load(ctx, symbol)
		if lerr != nil {
			return nil, fmt.Errorf("load symbol %s: %w", symbol, lerr)
		}
		if body, merr := json.Marshal(cfg); merr == nil {
			wctx, wcancel := context.WithTimeout(ctx, redisTimeout)
			_ = c.rdb.Set(wctx, key, body, jitter(symbolTTL)).Err() // 回填失败不影响主流程，但要有日志/指标
			wcancel()
		}
		return cfg, nil
	})
}

// Invalidate 写路径：**先写 MySQL，再调用本方法删缓存**。删除失败须重试 / 发 Kafka 事件补删。
func (c *SymbolCache) Invalidate(ctx context.Context, symbol string) error {
	ctx, cancel := context.WithTimeout(ctx, redisTimeout)
	defer cancel()
	return c.rdb.Del(ctx, symbolKey(symbol)).Err()
}

// ───────── 分布式锁 ─────────
// 锁只用于削峰 / 防重复提交，不是资金正确性的依据；正确性靠 MySQL 乐观锁 / 唯一键（redis.md §5）。

var unlockScript = goredis.NewScript(`
if redis.call("GET", KEYS[1]) == ARGV[1] then
  return redis.call("DEL", KEYS[1])
end
return 0`)

// ErrLockNotAcquired 获取锁失败。
var ErrLockNotAcquired = errors.New("lock not acquired")

// Locker 分布式锁。
type Locker struct{ rdb goredis.UniversalClient }

// NewLocker 构造函数注入。
func NewLocker(rdb goredis.UniversalClient) *Locker { return &Locker{rdb: rdb} }

// Acquire 加锁：key = lock:{业务域}:{资源类型}:{资源ID}。返回释放函数，调用方 defer 调用。
func (l *Locker) Acquire(ctx context.Context, biz, resource, id string, ttl time.Duration) (release func(), err error) {
	key := naming.RedisKey("lock", biz, resource+":"+id) // lock:{业务域}:{资源类型}:{资源ID}
	token := uuid.NewString()                            // 持有者标识：释放前校验，避免误删别人的锁
	ctx, cancel := context.WithTimeout(ctx, redisTimeout)
	defer cancel()
	ok, err := l.rdb.SetNX(ctx, key, token, ttl).Result()
	if err != nil {
		return nil, fmt.Errorf("acquire lock %s: %w", key, err)
	}
	if !ok {
		return nil, ErrLockNotAcquired
	}
	return func() {
		rctx, rcancel := context.WithTimeout(context.Background(), redisTimeout)
		defer rcancel()
		_ = unlockScript.Run(rctx, l.rdb, []string{key}, token).Err() // Lua：校验 token 后才 DEL
	}, nil
}

// Demo: 结构化日志 + trace_id — 公共库 logging（基于 slog，JSON 输出）
